// Extract subject and text from input
const subject = $input.item.json.Subject || '';
const text = $input.item.json.snippet || '';

// Determine API type from subject
let apiType = '';
let apiDisplayName = '';

if (subject.includes('BFL_LEAD_PUSH_STATUS')) {
  apiType = 'BFL';
  apiDisplayName = 'BFL Lead Push API';
} else if (subject.includes('BHFL_BULK_LEAD_PUSH_STATUS')) {
  apiType = 'BHFL_BULK';
  apiDisplayName = 'BHFL Bulk Lead Push API';
} else if (subject.includes('BHFL_LIVE_LEAD_PUSH_STATUS')) {
  apiType = 'BHFL_LIVE';
  apiDisplayName = 'BHFL Live Lead Push API';
} else if (subject.includes('BHFL_IVR_LEAD_PUSH_STATUS')) {
  apiType = 'BHFL_IVR';
  apiDisplayName = 'BHFL IVR Lead Push API';
} else if (subject.includes('BFDL_LEAD_PUSH_STATUS')) {
  apiType = 'BFDL';
  apiDisplayName = 'BFDL Lead Push API';
} else if (subject.includes('CC_LEAD_PUSH_STATUS')) {
  apiType = 'CC';
  apiDisplayName = 'CC Lead Push API';
} else {
  // Skip items that don't match any known API type
  return null;
}

// Extract count from text using regex
const countMatch = text.match(/Successful Leads\s+(\d+)/i);
const count = countMatch ? countMatch[1] : '0';

// Get current date and time
const currentDate = new Date();
const dateStr = currentDate.toISOString().split('T')[0]; // YYYY-MM-DD
const timeStr = currentDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

// Extract email headers
const from = $input.item.json.From || $input.item.json.from || '';
const to = $input.item.json.To || $input.item.json.to || '';
const receivedDate = $input.item.json.ReceivedDate || $input.item.json.date || $input.item.json.internalDate || '';

// Format timestamp
let timestamp = '';
if (receivedDate) {
  const ts = parseInt(receivedDate);
  timestamp = new Date(ts).toISOString();
} else {
  timestamp = currentDate.toISOString();
}

// Format output message for Hangout
let formattedMessage = '';
switch(apiType) {
  case 'BFL':
    formattedMessage = 'BFL Lead push API is working fine.\nPlease find the Successful Lead Push count till 10.00 AM : ' + count;
    break;
  case 'BHFL_BULK':
    formattedMessage = 'BHFL Bulk Lead push API is working fine.\nPlease find the Successful Lead Push count till 10.00 AM: ' + count;
    break;
  case 'BHFL_LIVE':
    formattedMessage = 'BHFL Live Lead push API is working fine.\nPlease find the Successful Lead Push count till 10.00 AM : ' + count;
    break;
  case 'BHFL_IVR':
    formattedMessage = 'BHFL IVR API lead push is working fine.\nPlease find the Successful Lead Push count till 10.00 AM : ' + count;
    break;
  case 'BFDL':
    formattedMessage = 'BFDL lead push API is working fine.\nPlease find the Successful Lead Push count till 10.00 AM : ' + count;
    break;
  case 'CC':
    formattedMessage = 'CC lead push API is working fine.\nPlease find the Successful Lead Push count till 10.00 AM : ' + count;
    break;
}

// Return data for both Hangout AND Excel/Google Sheets
return {
  // For Hangout message
  apiType: apiType,
  count: count,
  formattedMessage: formattedMessage,
  subject: subject,

  // For Excel/Google Sheets (headers)
  sheetData: {
    date: dateStr,
    time: timeStr,
    timestamp: timestamp,
    apiName: apiDisplayName,
    apiType: apiType,
    leadCount: parseInt(count),
    subject: subject,
    from: from,
    to: to,
    status: 'Success',
    executionTime: timeStr
  }
};

// Get all formatted messages from aggregated data
const messages = $input.first().json.formattedMessage;

// Join all messages with double newline
const finalMessage = messages.join('\n\n');

return { message: finalMessage };

const subject = $input.item.json.Subject;
const snippet = $input.item.json.snippet;

// Extract IP address from subject
const ipMatch = subject.match(/(\d+\.\d+\.\d+\.\d+)/);
const ipAddress = ipMatch ? ipMatch[1] : "";

// Extract numbers from table
const tableMatch = snippet.match(/(\d+\.?\d*[GT])\s*\|?\s*(\d+\.?\d*[GT])\s*\|?\s*(\d+)%/);

let usedSpace = "N/A";
let availableSpace = "N/A";
let usedPercent = 0;
let totalSpace = "N/A";

if (tableMatch) {
  usedSpace = tableMatch[1];
  availableSpace = tableMatch[2];
  usedPercent = parseInt(tableMatch[3]);

  const usedNum = parseFloat(usedSpace);
  const availNum = parseFloat(availableSpace);
  const unit = usedSpace.match(/[GT]/)[0];
  totalSpace = (usedNum + availNum).toFixed(1) + unit;
}

// Status
let status = "Healthy";
let emoji = "🟢";
if (usedPercent >= 85) {
  status = "Critical";
  emoji = "🔴";
} else if (usedPercent >= 70) {
  status = "Warning";
  emoji = "🟡";
}

// Server name based on email subject
let serverName = "Unknown";
if (subject.includes("BFL Portal")) serverName = "BFL-PROD/CRM";
else if (subject.includes("BFL Middleware")) serverName = "BFL Production";
else if (subject.includes("BHFL BULK")) serverName = "BHFL BULK Portal";
else if (subject.includes("BHFL Rechurn")) serverName = "BHFL Rechurn";
else if (subject.includes("BFDL")) serverName = "BFDL";
else if (subject.includes("Credit Card")) serverName = "Credit Card";

// Add IP to server name
const displayName = ipAddress ? `${serverName} (${ipAddress})` : serverName;

return {
  serverName: displayName,
  usedSpace: usedSpace,
  availableSpace: availableSpace,
  totalSpace: totalSpace,
  usedPercent: usedPercent,
  status: status,
  emoji: emoji
};

const allItems = $input.all();
let finalMessage = "DISK SPACE STATUS REPORT\n\n";
let criticalServers = [];
let warningServers = [];

for (let i = 0; i < allItems.length; i++) {
  const data = allItems[i].json;

  if (!data.serverName) continue;

  // Fix server names
  let serverName = data.serverName;
  if (serverName === "BFDL Credit Card") serverName = "Credit Card";
  if (serverName === "BFL ALL Production") serverName = "BFL Production";

  // Calculate total and available from used and percent
  let usedSpace = data.usedSpace || "N/A";
  let usedPercent = data.usedPercent || 0;
  let totalSpace = data.totalSpace || "N/A";
  let availableSpace = data.availableSpace || "N/A";

  if (usedSpace !== "N/A" && totalSpace === "N/A" && usedPercent > 0) {
    const usedNum = parseFloat(usedSpace);
    const unit = usedSpace.match(/[GT]/) ? usedSpace.slice(-1) : "G";
    const totalNum = (usedNum * 100) / usedPercent;
    const availableNum = totalNum - usedNum;
    totalSpace = totalNum.toFixed(1) + unit;
    availableSpace = availableNum.toFixed(1) + unit;
  }

  const emoji = data.emoji || (data.status === "Warning" ? "🟡" : "🟢");
  const status = data.status || "Healthy";

  finalMessage = finalMessage + `${emoji} *${serverName}*: ${usedSpace} used, ${availableSpace} available (Total: ${totalSpace}) - ${usedPercent}% - ${status}\n`;

  if (status === "Critical") {
    criticalServers.push(serverName + " (" + usedPercent + "%)");
  } else if (status === "Warning") {
    warningServers.push(serverName + " (" + usedPercent + "%)");
  }
}

if (criticalServers.length > 0) {
  finalMessage = finalMessage + `\n🔴 CRITICAL: ${criticalServers.join(", ")} - Immediate action required!`;
} else if (warningServers.length > 0) {
  finalMessage = finalMessage + `\n⚠️ WARNING: ${warningServers.join(", ")} - Monitor closely`;
}

return { message: finalMessage };

const emailText = $json.text || $json.html || "";

// Parse the table - look for lines with | and extract data
const lines = emailText.split('\n');
const backupData = [];
let currentServer = "";
let currentFiles = [];

// Extract dynamic date from email
let reportDate = "";

// Try to get date from $json.date field first
if ($json.date) {
  // Parse date like "Date: Mon, 08 Jun 2026 09:15:05 +0530"
  const dateMatch = $json.date.match(/\d{2} (?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4}/);
  if (dateMatch) {
    const parsedDate = new Date(dateMatch[0]);
    if (!isNaN(parsedDate)) {
      reportDate = parsedDate.toISOString().split('T')[0]; // YYYY-MM-DD
    }
  }
}

// If not found, try to extract from report body (e.g., "BACKUP SIZE REPORT FOR DATE: 080626")
if (!reportDate) {
  const dateInReport = emailText.match(/DATE:\s*(\d{2})(\d{2})(\d{2})/);
  if (dateInReport) {
    const day = dateInReport[1];
    const month = dateInReport[2];
    const year = `20${dateInReport[3]}`;
    reportDate = `${year}-${month}-${day}`;
  }
}

// Fallback to current date if nothing found
if (!reportDate) {
  const today = new Date();
  reportDate = today.toISOString().split('T')[0];
}

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];

  // Look for table rows (have | but not +---+)
  if (line.includes('|') && !line.includes('+---')) {

    // Split by pipe and clean
    const parts = line.split('|').map(p => p.trim());

    const parentFolder = parts[1] || "";
    const fileName = parts[3] || "";
    const fileSize = parts[4] || "";

    // Skip header row
    if (fileName === "FILE NAME") continue;
    if (fileName === "") continue;
    if (fileName === "DATE FOLDER") continue;

    // If we have a new server
    if (parentFolder && parentFolder !== "" && parentFolder !== "PARENT FOLDER") {
      // Save previous server
      if (currentServer && currentFiles.length > 0) {
        backupData.push({ ip: currentServer, files: [...currentFiles] });
        currentFiles = [];
      }
      currentServer = parentFolder;
    }

    // Add file if we have a valid name
    if (fileName && fileName !== "") {
      currentFiles.push(`${fileName}|${fileSize}`);
    }
  }
}

// Save last server
if (currentServer && currentFiles.length > 0) {
  backupData.push({ ip: currentServer, files: [...currentFiles] });
}

// Build message with dynamic date
let message = "NAS BACKUP REPORT\n";
message += "Date: " + reportDate + "\n\n";  // ← Dynamic date, not hardcoded!

for (let s = 0; s < backupData.length; s++) {
  const server = backupData[s];
  message += "========================================\n";
  message += "Server: " + server.ip + "\n";
  message += "----------------------------------------\n";

  for (let f = 0; f < server.files.length; f++) {
    const file = server.files[f];
    const [fileName, fileSize] = file.split("|");
    message += "   File: " + fileName + " | Size: " + fileSize + "\n";
  }
  message += "\n";
}

// Debug: Log count
message += `\nTotal servers: ${backupData.length}\n`;

return { message: message };
